    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Uniform lines in a color other than the background are tile dividers.
    sep_rows = {
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    }
    sep_cols = {
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    }

    def segments(n, separators):
        result, start = [], 0
        for i in range(n):
            if i in separators:
                if start < i:
                    result.append((start, i))
                start = i + 1
        if start < n:
            result.append((start, n))
        return result

    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)

    # Select the tile containing the pattern, then repeat it in every tile.
    source = None
    best_score = -1
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            score = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            if score > best_score:
                best_score = score
                source = (r0, r1, c0, c1)

    r0, r1, c0, c1 = source
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]
    out = [row[:] for row in grid]

    for tr0, tr1 in row_segments:
        for tc0, tc1 in col_segments:
            if tr1 - tr0 == len(pattern) and tc1 - tc0 == len(pattern[0]):
                for dr in range(len(pattern)):
